export const ARTICLES: Article[] = [{"id":"art_bx2_01","moduleId":"MODULE_BX_2","title":"子路、曾皙、冉有、公西华侍坐","subtitle":null,"author":"论语","dynasty":"先秦","genre":"散文","isGaoKao72":true,"recitationScope":"曾皙言志及孔子赞叹段（点，尔何如……吾与点也）","fullContent":"“点！尔何如？”鼓瑟希，铿尔，舍瑟而作，对曰：“异乎三子者之撰。”子曰：“何伤乎？亦各言其志也。”曰：“莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。”夫子喟然叹曰：“吾与点也！”","paragraphs":["“点！尔何如？”鼓瑟希，铿尔，舍瑟而作，对曰：“异乎三子者之撰。”","子曰：“何伤乎？亦各言其志也。”曰：“莫春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。”夫子喟然叹曰：“吾与点也！”"],"translation":"孔子问曾皙的志向。曾皙说暮春时节，带五六位成年人、六七个少年在沂水边沐浴，在舞雩台上吹风，然后一路唱着歌回来。孔子叹道：“我赞同曾皙。”","annotations":["哂（shěn）之：微笑赞许兼有轻讽。","风乎舞雩：在舞雩台吹风乘凉。"],"sortOrder":1,"totalSegments":6,"totalCards":6},{"id":"art_bx2_02","moduleId":"MODULE_BX_2","title":"齐桓晋文之事","subtitle":null,"author":"孟子","dynasty":"先秦","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"齐宣王问曰：“齐桓、晋文之事可得闻乎？”孟子对曰：“仲尼之徒无道桓、文之事者，是以后世无传焉。臣未之闻也。无以，则王乎？”曰：“德何如，则可以王矣？”曰：“保民而王，莫之能御也。”\n曰：“若寡人者，可以保民乎哉？”曰：“可。”曰：“何由知吾可也？”曰：“臣闻之胡龁曰，王坐于堂上，有牵牛而过堂下者，王见之，曰：‘牛何之？’对曰：‘将以衅钟。’王曰：‘舍之！吾不忍其觳觫，若无罪而就死地。’对曰：‘然则废衅钟与？’曰：‘何可废也？以羊易之！’不识有诸？”曰：“有之。”曰：“是心足以王矣。百姓皆以王为爱也，臣固知王之不忍也。”","paragraphs":["齐宣王问曰：“齐桓、晋文之事可得闻乎？”孟子对曰：“仲尼之徒无道桓、文之事者”","老吾老，以及人之老；幼吾幼，以及人之幼。天下可运于掌。"],"translation":"齐宣王问道：“齐桓公、晋文公称霸的事可以讲给我听听吗？”。","annotations":["衅钟：古代新钟铸成用牲血涂钟行祭。","觳觫（hú sù）：恐惧发抖貌。"],"sortOrder":2,"totalSegments":6,"totalCards":6},{"id":"art_bx2_03","moduleId":"MODULE_BX_2","title":"庖丁解牛","subtitle":null,"author":"庄周","dynasty":"先秦","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦，砉然向然，奏刀騞然，莫不中音。合于《桑林》之舞，乃中《经首》之会。\n文惠君曰：“嘻，善哉！技盖至此乎？”\n庖丁释刀对曰：“臣之所好者道也，进乎技矣。始臣之解牛之时，所见无非牛者。三年之后，未尝见全牛也。方今之时，臣以神遇而不以目视，官知止而神欲行。依乎天理，批大郤，导大窾，因其固然，技经肯綮之未尝，而况大軱乎！良庖岁更刀，割也；族庖月更刀，折也。今臣之刀十九年矣，所解数千牛矣，而刀刃若新发于硎。彼节者有间，而刀刃者无厚；以无厚入有间，恢恢乎其于游刃必有余地矣，是以十九年而刀刃若新发于硎。虽然，每至于族，吾见其难为，怵然为戒，视为止，行为迟。动刀甚微，謋然已解，如土委地。提刀而立，为之四顾，为之踌躇满志，善刀而藏之。”\n文惠君曰：“善哉！吾闻庖丁之言，得养生焉。”","paragraphs":["庖丁为文惠君解牛，手之所触，肩之所倚，足之所履，膝之所踦。","臣之所好者道也，进乎技矣。始臣之解牛之时，所见无非牛者。三年之后，未尝见全牛也。","以无厚入有间，恢恢乎其于游刃必有余地矣。"],"translation":"庖丁替梁惠王宰牛，手所接触的地方，肩膀所靠的地方。","annotations":["进乎技：超过技术层面达到道。","游刃有余：运转刀刃宽绰有余地。"],"sortOrder":3,"totalSegments":6,"totalCards":6},{"id":"art_bx2_04","moduleId":"MODULE_BX_2","title":"烛之武退秦师","subtitle":null,"author":"左丘明","dynasty":"先秦","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。晋军函陵，秦军氾南。\n佚之狐言于郑伯曰：“国危矣，若使烛之武见秦君，师必退。”公从之。辞曰：“臣之壮也，犹不如人；今老矣，无能为也已。”公曰：“吾不能早用子，今急而求子，是寡人之过也。然郑亡，子亦有不利焉！”许之。\n夜缒而出，见秦伯，曰：“秦、晋围郑，郑既知亡矣。若亡郑而有益于君，敢以烦执事。越国以鄙远，君知其难也，焉用亡郑以陪邻？邻之厚，君之薄也。若舍郑以为东道主，行李之往来，共其乏困，君亦无所害。且君尝为晋君赐矣，许君焦、瑕，朝济而夕设版焉，君之所知也。夫晋，何厌之有？既东封郑，又欲肆其西封，若不阙秦，将焉取之？阙秦以利晋，唯君图之。”秦伯说，与郑人盟。使杞子、逢孙、杨孙戍之，乃还。\n子犯请击之。公曰：“不可。微夫人之力不及此。因人之力而敝之，不仁；失其所与，不知；以乱易整，不武。吾其还也。”亦去之。","paragraphs":["晋侯、秦伯围郑，以其无礼于晋，且贰于楚也。","夜缒而出，见秦伯，曰：“秦、晋围郑，郑既知亡矣”","微夫人之力不及此。因人之力而敝之，不仁；失其所与，不知；以乱易整，不武。"],"translation":"晋文公和秦穆公联合围攻郑国。","annotations":["东道主：东方道路上的主人。","行李：外交使节。"],"sortOrder":4,"totalSegments":5,"totalCards":5},{"id":"art_bx2_05","moduleId":"MODULE_BX_2","title":"鸿门宴","subtitle":null,"author":"司马迁","dynasty":"西汉","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"沛公军霸上，未得与项羽相见。沛公左司马曹无伤使人言于项羽曰：“沛公欲王关中，使子婴为相，珍宝尽有之。”项羽大怒曰：“旦日飨士卒，为击破沛公军！”\n楚左尹项伯者，项羽季父也，素善留侯张良。张良是时从沛公，项伯乃夜驰之沛公军，私见张良，具告以事，欲呼张良与俱去，曰：“毋从俱死也。”\n沛公旦日从百余骑来见项王，至鸿门，谢曰：“臣与将军戮力而攻秦，将军战河北，臣战河南，然不自意能先入关破秦，得复见将军于此。今者有小人之言，令将军与臣有郤。”项王曰：“此沛公左司马曹无伤言之。不然，籍何以至此？”\n项庄拔剑起舞。项伯亦拔剑起舞，常以身翼蔽沛公，庄不得击。\n哙遂入，披帷西向立，瞋目视项王，头发上指，目眦尽裂。项王按剑而跽曰：“壮士！——赐之卮酒。”\n沛公已出，项王使都尉陈平召沛公。沛公曰：“今者出，未辞也，为之奈何？”樊哙曰：“大行不顾细谨，大礼不辞小让。如今人方为刀俎，我为鱼肉，何辞为？”遂去。","paragraphs":["沛公军霸上，未得与项羽相见。","项庄拔剑起舞。项伯亦拔剑起舞，常以身翼蔽沛公，庄不得击。","如今人方为刀俎，我为鱼肉，何辞为？"],"translation":"刘邦驻军霸上，还没能同项羽相见。","annotations":["项庄舞剑意在沛公：比喻说话行动意在谋害他人。","人为刀俎我为鱼肉：比喻处于受人宰割的地位。"],"sortOrder":5,"totalSegments":8,"totalCards":8},{"id":"art_bx2_06","moduleId":"MODULE_BX_2","title":"窦娥冤","subtitle":null,"author":"关汉卿","dynasty":"元代","genre":"曲","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"【滚绣球】有日月朝暮悬，有鬼神掌着生死权。天地也！只合把清浊分辨，可怎生糊突了盗跖、颜渊？为善的受贫穷更命短，造恶的享富贵又寿延。天地也！做得个怕硬欺软，却原来也这般顺水推船！地也，你不分好歹何为地！天也，你错勘贤愚枉做天！哎，只落得两泪涟涟。","paragraphs":["【滚绣球】有日月朝暮悬，有鬼神掌着生死权。","地也，你不分好歹何为地！天也，你错勘贤愚枉做天！"],"translation":"天地日夜高悬，鬼神掌管生死大权。","annotations":["错勘：错误审断。","盗跖颜渊：盗贼与圣贤对比。"],"sortOrder":6,"totalSegments":3,"totalCards":3},{"id":"art_bx2_07","moduleId":"MODULE_BX_2","title":"谏逐客书","subtitle":"核心必背·第4段","author":"李斯","dynasty":"秦代","genre":"散文","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"臣闻地广者粟多，大国者人众，兵强则士勇。是以泰山不让土壤，故能成其大；河海不择细流，故能就其深；王者不却众庶，故能明其德。是以地无四方，民无异国，四时充美，鬼神降福，此五帝三王之所以无敌也。今乃弃黔首以资敌国，却宾客以业诸侯，使天下之士退而不敢西向，裹足不入秦，此所谓‘藉寇兵而赍盗粮’者也。","paragraphs":["臣闻地广者粟多，大国者人众，兵强则士勇。","是以泰山不让土壤，故能成其大；河海不择细流，故能就其深；王者不却众庶，故能明其德。","是以地无四方，民无异国，四时充美，鬼神降福，此五帝三王之所以无敌也。","今乃弃黔首以资敌国，却宾客以业诸侯，使天下之士退而不敢西向，裹足不入秦，此所谓‘藉寇兵而赍盗粮’者也。"],"translation":"我听说官吏在商议驱逐客卿，私下认为这是错误的。","annotations":["河海不择细流：博采众长兼容并包。"],"sortOrder":7,"totalSegments":5,"totalCards":5},{"id":"art_bx2_08","moduleId":"MODULE_BX_2","title":"与妻书","subtitle":null,"author":"林觉民","dynasty":"清末","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"意映卿卿如晤：吾今以此书与汝永别矣！吾作此书，泪珠和笔墨齐下，不能竟书而欲搁笔，又恐汝不察吾衷，谓吾忍舍汝而死，谓吾不知汝之不欲吾死也，故遂忍悲为汝言之。\n吾至爱汝，即此爱汝一念，使吾勇于就死也。吾自遇汝以来，常愿天下有情人都成眷属；然遍地腥云，满街狼犬，称心快意，几家能彀？司马青衫，吾不能学太上之忘情也。\n吾今死无余憾，国事成不成自有同志者在。依新已五岁，转眼成人，汝其善抚之，使之肖我。汝腹中之物，吾疑其女也，女必像汝，吾心甚慰。或又是男，则亦教其以父志为志，则我死后尚有二意映在旁，吾家后日当甚旺。吾家日后当甚微，汝幸而偶我，又何不幸而生今日中国！吾幸而得汝，又何不幸而生今日之中国！卒不忍独善其身。","paragraphs":["意映卿卿如晤：吾今以此书与汝永别矣！","吾至爱汝，即此爱汝一念，使吾勇于就死也。"],"translation":"意映我的爱妻，如同当面见到你一样。","annotations":["如晤：如同当面相见。","太上忘情：圣人不为情所动。"],"sortOrder":8,"totalSegments":3,"totalCards":3},{"id":"art_bx2_09","moduleId":"MODULE_BX_2","title":"促织","subtitle":null,"author":"蒲松龄","dynasty":"清代","genre":"散文","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"宣德间，宫中尚促织之戏，岁征民间。此物故非陇西产，以市各部，司市者私增其秩。成名者，操童子业，久不售。为人迂讷，遂为猾黠胥吏所中，神名籍中，按岁征织。","paragraphs":["宣德间，宫中尚促织之戏，岁征民间。","一人飞升，仙及鸡犬。天子偶用一物，未必不过此已。"],"translation":"宣德年间，宫廷里崇尚斗蟋蟀的游戏。","annotations":["促织：蟋蟀。","成名：人名。"],"sortOrder":9,"totalSegments":3,"totalCards":3},{"id":"art_bx2_10","moduleId":"MODULE_BX_2","title":"谏太宗十思疏","subtitle":null,"author":"魏征","dynasty":"唐代","genre":"散文","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"臣闻求木之长者，必固其根本；欲流之远者，必浚其泉源；思国之安者，必积其德义。源不深而望流之远，根不固而求木之长，德不厚而思国之理，臣虽下愚，知其不可，而况于明哲乎！人君当神器之重，居域中之大，将崇极天之峻，永保无疆之休。不念居安思危，戒奢以俭，德不处其厚，情不胜其欲，斯亦伐根以求木茂，塞源而欲流长也。\n凡百元首，承天景命，莫不殷忧而道著，功成而德衰。有善始者实繁，能克终者盖寡。岂其取之易而守之难乎？昔取之而有余，今守之而不足，何也？夫在殷忧，必竭诚以待下；既得志，则纵情以傲物。竭诚则胡越为一体，傲物则骨肉为行路。虽董之以严刑，振之以威怒，终苟免而不怀仁，貌恭而不心服。怨不在大，可畏惟人；载舟覆舟，所宜深慎；奔车朽索，其可忽乎！\n君人者，诚能见可欲则思知足以自戒，将有作则思知止以安人，念高危则思谦冲而自牧，惧满溢则思江海下百川，乐盘游则思三驱以为度，忧懈怠则思慎始而敬终，虑壅蔽则思虚心以纳下，想谗邪则思正身以黜恶，恩所加则思无因喜以谬赏，罚所及则思无因怒而滥刑。总此十思，弘兹九德，简能而任之，择善而从之，则智者尽其谋，勇者竭其力，仁者播其惠，信者效其忠。文武争驰，在君无事，可以尽豫游之乐，可以养松、乔之寿，鸣琴垂拱，不言而化。何必劳神苦思，代下司职，役聪明之耳目，亏无为之大道哉！","paragraphs":["臣闻求木之长者，必固其根本；欲流之远者，必浚其泉源；思国之安者，必积其德义。","善始者实繁，能克终者盖寡。载舟覆舟，所宜深慎；奔车朽索，其可忽乎！","总此十思，弘兹九德，鸣琴垂拱，不言而化。"],"translation":"我听说想让树木长得高大，一定要稳固它的根基。","annotations":["求木之长者必固其根本：比喻积德深厚方能治国。","载舟覆舟：百姓如水，君如舟。"],"sortOrder":10,"totalSegments":8,"totalCards":8},{"id":"art_bx2_11","moduleId":"MODULE_BX_2","title":"答司马谏议书","subtitle":null,"author":"王安石","dynasty":"宋代","genre":"散文","isGaoKao72":true,"recitationScope":"第2、3段（坚持变法、逐条驳斥）","fullContent":"人习于苟且非一日，士大夫多以不恤国事、同俗自媚于众为善，上乃欲变此，而某不量敌之众寡，欲以此抗之，是以举天下之人皆反对此议。盘庚迁都，胥怨者民也，非特朝廷士大夫而已；盘庚不为怨者故改其度，度义而后动，是何也？缓急有素，情见势极，不可改也。\n如君实所指：侵官、生事、征利、拒谏，以致天下怨谤也。某则以为受命于人主，议法度而修之于朝廷，以授之于有司，不为侵官；举先王之政，以兴利除弊，不为生事；为天下理财，不为征利；辟邪说，难壬人，不为拒谏。至于怨诽之多，则固前知其如此也。","paragraphs":["人习于苟且非一日，士大夫多以不恤国事、同俗自媚于众为善，上乃欲变此，而某不量敌之众寡，欲以此抗之，是以举天下之人皆反对此议。盘庚迁都，胥怨者民也，非特朝廷士大夫而已；盘庚不为怨者故改其度，度义而后动，是何也？缓急有素，情见势极，不可改也。","如君实所指：侵官、生事、征利、拒谏，以致天下怨谤也。某则以为受命于人主，议法度而修之于朝廷，以授之于有司，不为侵官；举先王之政，以兴利除弊，不为生事；为天下理财，不为征利；辟邪说，难壬人，不为拒谏。至于怨诽之多，则固前知其如此也。"],"translation":"王安石启奏：昨天承蒙赐教，我私下认为和君实相交深厚。","annotations":["司马谏议：司马光。","度义而后动：衡量合乎道义而后行动。"],"sortOrder":11,"totalSegments":4,"totalCards":4},{"id":"art_bx2_12","moduleId":"MODULE_BX_2","title":"阿房宫赋","subtitle":null,"author":"杜牧","dynasty":"唐代","genre":"文赋","isGaoKao72":true,"recitationScope":"第1、2、4、5段（建筑、宫人珍宝、秦亡、后人教训）","fullContent":"六王毕，四海一，蜀山兀，阿房出。覆压三百余里，隔离天日。骊山北构而西折，直走咸阳。二川溶溶，流入宫墙。五步一楼，十步一阁；廊腰缦回，檐牙高啄；各抱地势，钩心斗角。盘盘焉，囷囷焉，蜂房水涡，矗不知其几千万落。长桥卧波，未云何龙？复道行空，不霁何虹？高低冥迷，不知西东。歌台暖响，春光融融；舞殿冷袖，风雨凄凄。一日之内，一宫之间，而气候不齐。\n妃嫔媵嫱，王子皇孙，辞楼下殿，辇来于秦。朝歌夜弦，为秦宫人。明星荧荧，开妆镜也；绿云扰扰，梳晓鬟也；渭流涨腻，弃脂水也；烟斜雾横，焚椒兰也。雷霆乍惊，宫车过也；辘辘远听，杳不知其所之也。一肌一容，尽态极妍，缦立远视，而望幸焉。有不得见者，三十六年。\n嗟乎！一人之心，千万人之心也。秦爱纷奢，人亦念其家。奈何取之尽锱铢，用之如泥沙？使负栋之柱，多于南亩之农夫；架梁之椽，多于机上之工女；钉头磷磷，多于在庾之粟粒；瓦缝参差，多于周身之帛缕；直栏横槛，多于九土之城郭；管弦呕哑，多于市人之言语。使天下之人，不敢言而敢怒。独夫之心，日益骄固。戍卒叫，函谷举，楚人一炬，可怜焦土！\n呜呼！灭六国者六国也，非秦也；族秦者秦也，非天下也。嗟乎！使六国各爱其人，则足以拒秦；使秦复爱六国之人，则递三世可至万世而为君，谁得而族灭也？秦人不暇自哀，而后人哀之；后人哀之而不鉴之，亦使后人而复哀后人也。","paragraphs":["六王毕，四海一，蜀山兀，阿房出。覆压三百余里，隔离天日。骊山北构而西折，直走咸阳。二川溶溶，流入宫墙。五步一楼，十步一阁；廊腰缦回，檐牙高啄；各抱地势，钩心斗角。盘盘焉，囷囷焉，蜂房水涡，矗不知其几千万落。长桥卧波，未云何龙？复道行空，不霁何虹？高低冥迷，不知西东。歌台暖响，春光融融；舞殿冷袖，风雨凄凄。一日之内，一宫之间，而气候不齐。","妃嫔媵嫱，王子皇孙，辞楼下殿，辇来于秦。朝歌夜弦，为秦宫人。明星荧荧，开妆镜也；绿云扰扰，梳晓鬟也；渭流涨腻，弃脂水也；烟斜雾横，焚椒兰也。雷霆乍惊，宫车过也；辘辘远听，杳不知其所之也。一肌一容，尽态极妍，缦立远视，而望幸焉。有不得见者，三十六年。","嗟乎！一人之心，千万人之心也。秦爱纷奢，人亦念其家。奈何取之尽锱铢，用之如泥沙？使负栋之柱，多于南亩之农夫；架梁之椽，多于机上之工女；钉头磷磷，多于在庾之粟粒；瓦缝参差，多于周身之帛缕；直栏横槛，多于九土之城郭；管弦呕哑，多于市人之言语。使天下之人，不敢言而敢怒。独夫之心，日益骄固。戍卒叫，函谷举，楚人一炬，可怜焦土！","呜呼！灭六国者六国也，非秦也；族秦者秦也，非天下也。嗟乎！使六国各爱其人，则足以拒秦；使秦复爱六国之人，则递三世可至万世而为君，谁得而族灭也？秦人不暇自哀，而后人哀之；后人哀之而不鉴之，亦使后人而复哀后人也。"],"translation":"六国灭亡，四海统一，蜀山树木被砍光，阿房宫建造出来。","annotations":["钩心斗角：指宫室结构参差错落、精巧工致。","取之尽锱铢用之如泥沙：极言搜刮之贪、挥霍之奢。"],"sortOrder":12,"totalSegments":12,"totalCards":12},{"id":"art_bx2_13","moduleId":"MODULE_BX_2","title":"六国论","subtitle":null,"author":"苏洵","dynasty":"宋代","genre":"散文","isGaoKao72":true,"recitationScope":"第1、2、4、5段（中心论点、赂秦之害、为国者之戒、借古讽今）","fullContent":"六国破灭，非兵不利，战不善，弊在赂秦。赂秦而力亏，破灭之道也。或曰：六国互丧，率赂秦耶？曰：不赂者以赂者丧，盖失强援，不能独完。故曰：弊在赂秦也。\n秦以攻取之外，小则获邑，大则得城。较秦之所得，与战胜而得者，其实百倍；诸侯之所亡，与战败而亡者，其实亦百倍。则秦之所大欲，诸侯之所大患，固不在战矣。思厥先祖父，暴霜露，斩荆棘，以有尺寸之地。子孙视之不甚惜，举以予人，如弃草芥。今日割五城，明日割十城，然后得一夕安寝。起视四境，而秦兵又至矣。然则诸侯之地有限，暴秦之欲无厌，奉之弥繁，侵之愈急。故不战而强弱胜负已判矣。至于颠覆，理固宜然。古人云：“以地事秦，犹抱薪救火，薪不尽，火不灭。”此言得之。\n呜呼！以赂秦之地，封天下之谋臣；以事秦之心，礼天下之奇才；并力西向，则吾恐秦人食之不得下咽也。悲夫！有如此之势，而为秦人积威之所劫，日削月割，以趋于亡。为国者无使为积威之所劫哉！\n夫六国与秦皆诸侯，其势弱于秦，而犹有可以不赂而胜之之势。苟以天下之大，下而从六国破亡之故事，是又在六国下矣。","paragraphs":["六国破灭，非兵不利，战不善，弊在赂秦。赂秦而力亏，破灭之道也。或曰：六国互丧，率赂秦耶？曰：不赂者以赂者丧，盖失强援，不能独完。故曰：弊在赂秦也。","秦以攻取之外，小则获邑，大则得城。较秦之所得，与战胜而得者，其实百倍；诸侯之所亡，与战败而亡者，其实亦百倍。则秦之所大欲，诸侯之所大患，固不在战矣。思厥先祖父，暴霜露，斩荆棘，以有尺寸之地。子孙视之不甚惜，举以予人，如弃草芥。今日割五城，明日割十城，然后得一夕安寝。起视四境，而秦兵又至矣。然则诸侯之地有限，暴秦之欲无厌，奉之弥繁，侵之愈急。故不战而强弱胜负已判矣。至于颠覆，理固宜然。古人云：“以地事秦，犹抱薪救火，薪不尽，火不灭。”此言得之。","呜呼！以赂秦之地，封天下之谋臣；以事秦之心，礼天下之奇才；并力西向，则吾恐秦人食之不得下咽也。悲夫！有如此之势，而为秦人积威之所劫，日削月割，以趋于亡。为国者无使为积威之所劫哉！","夫六国与秦皆诸侯，其势弱于秦，而犹有可以不赂而胜之之势。苟以天下之大，下而从六国破亡之故事，是又在六国下矣。"],"translation":"六国灭亡，不是武器不锋利，仗打得不好，弊端在于贿赂秦国。","annotations":["弊在赂秦：破亡之关键在于向秦屈服割地。","抱薪救火：比喻用错误方法消灾，反而助长祸患。"],"sortOrder":13,"totalSegments":8,"totalCards":8},{"id":"art_bx2_recite_01","moduleId":"MODULE_BX_2_RECITE","title":"登岳阳楼","subtitle":null,"author":"杜甫","dynasty":"唐代","genre":"诗","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"昔闻洞庭水，今上岳阳楼。吴楚东南坼，乾坤日夜浮。亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。","paragraphs":["昔闻洞庭水，今上岳阳楼。吴楚东南坼，乾坤日夜浮。","亲朋无一字，老病有孤舟。戎马关山北，凭轩涕泗流。"],"translation":"早就听说洞庭湖波澜壮阔，今天终于登上了岳阳楼。","annotations":["吴楚东南坼：吴楚两地在此分裂裂开。","凭轩涕泗流：倚着栏杆眼泪止不住奔流。"],"sortOrder":1,"totalSegments":4,"totalCards":4},{"id":"art_bx2_recite_02","moduleId":"MODULE_BX_2_RECITE","title":"桂枝香·金陵怀古","subtitle":null,"author":"王安石","dynasty":"宋代","genre":"词","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"登临送目，正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。归帆去棹残阳里，背西风，酒旗斜矗。彩舟云淡，星河鹭起，画图难足。\n念往昔，繁华竞逐，叹门外楼头，悲恨相续。千古凭高对此，谩嗟荣辱。六朝旧事随流水，但寒烟衰草凝绿。至今商女，时时犹唱，后庭遗曲。","paragraphs":["登临送目，正故国晚秋，天气初肃。千里澄江似练，翠峰如簇。","念往昔，繁华竞逐，叹门外楼头，悲恨相续。六朝旧事随流水，但寒烟衰草凝绿。至今商女，时时犹唱，后庭遗曲。"],"translation":"登上高处放眼望去，正是故都金陵晚秋时节。","annotations":["千里澄江似练：浩荡长江清澈如同白绢。","门外楼头：化用陈后主降隋典故。"],"sortOrder":2,"totalSegments":4,"totalCards":4},{"id":"art_bx2_recite_03","moduleId":"MODULE_BX_2_RECITE","title":"念奴娇·过洞庭","subtitle":null,"author":"张孝祥","dynasty":"宋代","genre":"词","isGaoKao72":true,"recitationScope":"FULL_TEXT","fullContent":"洞庭青草，近中秋，更无一点风色。玉鉴琼田三万顷，着我扁舟一叶。素月分辉，明河共影，表里俱澄澈。悠然心会，妙处难与君说。\n应念岭表经年，孤光自照，肝胆皆冰雪。短发萧骚襟袖冷，稳泛沧浪空阔。尽吸西江，细斟北斗，万象为宾客。扣舷独啸，不知今夕何夕！","paragraphs":["洞庭青草，近中秋，更无一点风色。玉鉴琼田三万顷，着我扁舟一叶。","表里俱澄澈。悠然心会，妙处难与君说。尽吸西江，细斟北斗，万象为宾客。"],"translation":"洞庭湖与青草湖相接，临近中秋，湖面上没有一丝风。","annotations":["表里俱澄澈：由内而外一片纯洁澄净。","万象为宾客：以天地万物作为自己的宾客。"],"sortOrder":3,"totalSegments":4,"totalCards":4},{"id":"art_bx2_recite_04","moduleId":"MODULE_BX_2_RECITE","title":"游园","subtitle":null,"author":"汤显祖","dynasty":"明代","genre":"曲","isGaoKao72":false,"recitationScope":"非课标必背","fullContent":"【皂罗袍】原来姹紫嫣红开遍，似这般都付与断井颓垣。良辰美景奈何天，赏心乐事谁家院！朝飞暮卷，云霞翠轩；雨丝风片，烟波画船——锦屏人忒看的这韶光贱！","paragraphs":["原来姹紫嫣红开遍，似这般都付与断井颓垣。","良辰美景奈何天，赏心乐事谁家院！"],"translation":"原来百花盛开娇艳绚烂，却都交付给断垣残壁。","annotations":["良辰美景奈何天：好时光美风景徒然让人无可奈何。"],"sortOrder":4,"totalSegments":2,"totalCards":2}];
